struct book {
    short year;     // 2 bytes
    int   pages;    // 4 bytes
    char  shelf;    // 1 byte
};

struct date {
    short year;         // offset 0
    char  month;        // offset 2
};                      // 3 bytes of fields, padded to 4

struct loan {
    int         id;     // offset 0
    struct date out;    // offset 4
    struct date due;    // offset 8
};                      // 12 bytes
